#!/usr/bin/env bash
# Generated by commons/workload from the plan of synthetic-graph-02 0.1.0 (the form graph); do not edit it: regenerate it.
# It is only calls to the pinned verb command by verb id, loops over fixed lists and the order of the steps.
# plan: 64770c615c88c26b19f6eb79c0981939ca3f7a67998081327e0139c0de4e2ab3
# input: order (read from WORKLOAD_INPUT_ORDER)

if ((BASH_VERSINFO[0] < 5)); then
  printf 'workload: this script needs bash 5 or later\n' >&2
  exit 70
fi
set -Eeuo pipefail
shopt -s inherit_errexit

readonly plan_hash='64770c615c88c26b19f6eb79c0981939ca3f7a67998081327e0139c0de4e2ab3'
readonly workload_id='synthetic-graph-02'
readonly runner_id='bash'
readonly cli=('workload')
current_step='none'

on_exit() {
  local status="$1"
  printf 'workload.receipt/1 plan=%s workload=%s runner=%s status=%d step=%s\n' "${plan_hash}" "${workload_id}" "${runner_id}" "${status}" "${current_step}" >&2
}
trap 'on_exit "$?"' EXIT

run_verb() {
  current_step="$1"
  shift
  "${cli[@]}" verb "$@"
}

# step read-state: check, agent-autonomous
run_verb 'read-state' 'workbench.ready' --in 'task=run'
# step record-order: verb, agent-acts-human-reviews
run_verb 'record-order' 'work.record' --in "order=${WORKLOAD_INPUT_ORDER}"

current_step='done'
